def transform(grid):
    h,w=len(grid),len(grid[0])
    counts={}
    for row in grid:
        for x in row: counts[x]=counts.get(x,0)+1
    bg=max(counts,key=counts.get)
    mark=min(x for x in counts if x!=bg)
    out=[row[:] for row in grid]
    for r in range(h):
        cs=[c for c in range(w) if grid[r][c]==mark]
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=3
    for c in range(w):
        rs=[r for r in range(h) if grid[r][c]==mark]
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=3
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    mark = next(v for v in {v for row in grid for v in row} if v != bg)
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == mark]
    if not pts: return [row[:] for row in grid]
    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    out=[row[:] for row in grid]
    for r in (r0, r1):
        for c in range(c0, c1+1):
            if grid[r][c] == bg: out[r][c] = 2
    for c in (c0, c1):
        for r in range(r0, r1+1):
            if grid[r][c] == bg: out[r][c] = 2
    return out

