def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Fill each fully hollow rectangular frame. Demo evidence: 1x1, 3x3,
    # and 5x5 interiors take 7; 2x2 interiors take 2.
    for y0 in range(h):
        for y1 in range(y0 + 2, h):
            for x0 in range(w):
                for x1 in range(x0 + 2, w):
                    color = grid[y0][x0]
                    if color == bg:
                        continue
                    if not all(grid[y0][x] == color and grid[y1][x] == color for x in range(x0, x1 + 1)):
                        continue
                    if not all(grid[y][x0] == color and grid[y][x1] == color for y in range(y0, y1 + 1)):
                        continue
                    ih, iw = y1 - y0 - 1, x1 - x0 - 1
                    if not all(grid[y][x] == bg for y in range(y0 + 1, y1) for x in range(x0 + 1, x1)):
                        continue
                    fill = 7 if ih == iw and ih % 2 == 1 else 2
                    for y in range(y0 + 1, y1):
                        for x in range(x0 + 1, x1):
                            out[y][x] = fill
    return out
